import{_ as a,c as s,o as t,ag as n}from"./chunks/framework.CQuhCYrb.js";const h=JSON.parse('{"title":"Tailscale Exit Node","description":"","frontmatter":{"title":"Tailscale Exit Node"},"headers":[],"relativePath":"ai-ml/tailscale-exit-node.md","filePath":"ai-ml/tailscale-exit-node.md","lastUpdated":null}'),i={name:"ai-ml/tailscale-exit-node.md"};function l(r,e,o,p,c,d){return t(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="tailscale-exit-node" tabindex="-1">Tailscale Exit Node <a class="header-anchor" href="#tailscale-exit-node" aria-label="Permalink to &quot;Tailscale Exit Node&quot;">​</a></h1><h2 id="set-up-exit-node-with-tailscale" tabindex="-1">Set Up Exit Node with Tailscale <a class="header-anchor" href="#set-up-exit-node-with-tailscale" aria-label="Permalink to &quot;Set Up Exit Node with Tailscale&quot;">​</a></h2><p>Setting up an Exit Node with Tailscale allows you to route your internet traffic through a specific device in your network, providing enhanced privacy and flexibility. This guide outlines the configuration process and provides best practices for optimizing performance.</p><h3 id="exit-node-configuration" tabindex="-1">Exit Node Configuration <a class="header-anchor" href="#exit-node-configuration" aria-label="Permalink to &quot;Exit Node Configuration&quot;">​</a></h3><p>To configure a device as an exit node, use the following command:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>sudo tailscale up --advertise-exit-node</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>Once the device is set up as an exit node, you can select it as the preferred route in your Tailscale settings. For additional details, refer to the official Tailscale documentation:</p><ul><li><p><a href="https://tailscale.com/kb/1103/exit-nodes?tab=linux" target="_blank" rel="noreferrer">Tailscale Exit Nodes Guide</a></p></li><li><p><a href="https://tailscale.com/kb/1320/performance-best-practices#ethtool-configuration" target="_blank" rel="noreferrer">Performance Best Practices</a></p></li></ul><h3 id="auto-starting-tailscale" tabindex="-1">Auto-Starting Tailscale <a class="header-anchor" href="#auto-starting-tailscale" aria-label="Permalink to &quot;Auto-Starting Tailscale&quot;">​</a></h3><p>To ensure Tailscale starts automatically with the correct settings, follow these steps:</p><h3 id="_1-check-network-dispatcher-status" tabindex="-1">1. Check Network Dispatcher Status <a class="header-anchor" href="#_1-check-network-dispatcher-status" aria-label="Permalink to &quot;1. Check Network Dispatcher Status&quot;">​</a></h3><p>Verify if the <code>networkd-dispatcher</code> service is enabled:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>systemctl is-enabled networkd-dispatcher</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>If not, enable it by running:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>sudo systemctl enable networkd-dispatcher</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h3 id="_2-create-a-service-file-for-tailscale" tabindex="-1">2. Create a Service File for Tailscale <a class="header-anchor" href="#_2-create-a-service-file-for-tailscale" aria-label="Permalink to &quot;2. Create a Service File for Tailscale&quot;">​</a></h3><p>Create a custom <code>systemd</code> service to apply optimized <code>ethtool</code> settings for Tailscale:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>sudo nano /etc/systemd/system/ethtool-tailscale-settings.service</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>Add the following configuration:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Description=Apply ethtool settings for Tailscale optimizations</span></span>
<span class="line"><span>After=network.target</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[Service](Unit])</span></span>
<span class="line"><span>Type=oneshot</span></span>
<span class="line"><span>ExecStart=/bin/sh -c &#39;NETDEV=$(ip route show 0/0 | cut -f5 -d&quot; &quot;) &amp;&amp; ethtool -K $NETDEV rx-udp-gro-forwarding on rx-gro-list off&#39;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[WantedBy=multi-user.target</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><h3 id="_3-enable-the-service" tabindex="-1">3. Enable the Service <a class="header-anchor" href="#_3-enable-the-service" aria-label="Permalink to &quot;3. Enable the Service&quot;">​</a></h3><p>Enable the service so it starts automatically on boot:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>sudo systemctl enable ethtool-tailscale-settings.service</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h3 id="_4-start-the-service" tabindex="-1">4. Start the Service <a class="header-anchor" href="#_4-start-the-service" aria-label="Permalink to &quot;4. Start the Service&quot;">​</a></h3><p>Start the service immediately without rebooting:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>sudo systemctl start ethtool-tailscale-settings.service</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h3 id="best-practices-for-exit-node-performance" tabindex="-1">Best Practices for Exit Node Performance <a class="header-anchor" href="#best-practices-for-exit-node-performance" aria-label="Permalink to &quot;Best Practices for Exit Node Performance&quot;">​</a></h3><p>To optimize the performance of your Tailscale exit node, follow these guidelines:</p><ul><li><p><strong>Optimize Network Settings</strong>:</p><ul><li>Adjust the MTU (Maximum Transmission Unit) size for better performance.</li><li>Use tools like <code>ethtool</code> to fine-tune network settings.</li></ul></li><li><p><strong>Regular Software Updates</strong>:</p><ul><li>Keep Tailscale and your system software updated to leverage the latest improvements.</li></ul></li><li><p><strong>Monitor Traffic and Performance</strong>:</p><ul><li>Use monitoring tools like <code>iftop</code> or <code>vnstat</code> to keep track of network traffic and identify bottlenecks.</li></ul></li><li><p><strong>Use High-Performance Hardware</strong>:</p><ul><li>If possible, use a device with sufficient CPU and memory to handle the traffic demands of being an exit node.</li></ul></li></ul><h3 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h3><p>By setting up an exit node with Tailscale, you can improve your network&#39;s privacy and versatility. Following the outlined configuration and best practices ensures a reliable and high-performing exit node.</p>`,31)])])}const b=a(i,[["render",l]]);export{h as __pageData,b as default};
